// API v1 client, typed by the contract (schema.gen.ts, generated by `npm run gen:api`).
// Single origin: the app calls /api/v1 relative to its own origin, with the session cookie.
import createClient, { type Middleware } from 'openapi-fetch'
import type { components, paths } from './schema.gen'

export type Schemas = components['schemas']

const CSRF_COOKIE = 'eclume_csrf'
// The admin panel has its own session, with its own CSRF cookie.
const ADMIN_CSRF_COOKIE = 'eclume_admin_csrf'
export const CSRF_HEADER = 'X-CSRF-Token'
const SAFE_METHODS = new Set(['GET', 'HEAD', 'OPTIONS'])
const LOGIN_PATH = '/api/v1/auth/login'
const ADMIN_PREFIX = '/api/v1/admin/'
const ADMIN_LOGIN_PATH = '/api/v1/admin/auth/login'

/** The request belongs to the admin panel (admin session), not to the user session. */
export function isAdminUrl(url: string): boolean {
  return new URL(url, 'http://localhost').pathname.startsWith(ADMIN_PREFIX)
}

export function readCookie(name: string, cookies: string = globalThis.document?.cookie ?? ''): string | null {
  for (const pair of cookies.split(';')) {
    const [key, ...rest] = pair.trim().split('=')
    if (key === name) return decodeURIComponent(rest.join('='))
  }
  return null
}

/**
 * Double-submit: every mutating method echoes the area's session cookie in the `X-CSRF-Token` header:
 * `eclume_admin_csrf` under /api/v1/admin/, `eclume_csrf` everywhere else.
 */
const csrfMiddleware: Middleware = {
  onRequest({ request }) {
    if (!SAFE_METHODS.has(request.method)) {
      const token = readCookie(isAdminUrl(request.url) ? ADMIN_CSRF_COOKIE : CSRF_COOKIE)
      if (token) request.headers.set(CSRF_HEADER, token)
    }
    return request
  },
}

const unauthorizedListeners = new Set<() => void>()
const adminUnauthorizedListeners = new Set<() => void>()

function subscribe(listeners: Set<() => void>, listener: () => void): () => void {
  listeners.add(listener)
  return () => listeners.delete(listener)
}

/** Notifies when the API answers 401 to the user session (missing or expired), outside the login itself. */
export function onUnauthorized(listener: () => void): () => void {
  return subscribe(unauthorizedListeners, listener)
}

/** Notifies when the admin panel gets a 401 (admin session missing or expired), outside the admin login. */
export function onAdminUnauthorized(listener: () => void): () => void {
  return subscribe(adminUnauthorizedListeners, listener)
}

const unauthorizedMiddleware: Middleware = {
  onResponse({ response, schemaPath }) {
    if (response.status !== 401) return response
    // A 401 from the admin panel belongs to the admin session, and only the panel's guard listens to it.
    const admin = schemaPath.startsWith(ADMIN_PREFIX)
    const login = admin ? ADMIN_LOGIN_PATH : LOGIN_PATH
    if (schemaPath !== login) {
      for (const listener of admin ? adminUnauthorizedListeners : unauthorizedListeners) listener()
    }
    return response
  },
}

// Outside the browser (tests in the node environment) there is no origin; the base only needs to be absolute.
const ORIGIN = typeof window === 'undefined' ? 'http://localhost' : window.location.origin

export function createApiClient(baseUrl: string = ORIGIN) {
  const client = createClient<paths>({
    baseUrl,
    credentials: 'same-origin',
    // Resolves fetch on every call, so the tests can replace it.
    fetch: (request) => globalThis.fetch(request),
  })
  client.use(csrfMiddleware, unauthorizedMiddleware)
  return client
}

export type ApiClient = ReturnType<typeof createApiClient>

export const api = createApiClient()
